    "questionBody": "員警乙偵辦某件擄人勒贖案，發現 16 歲少年甲涉有重嫌。某日欲前往甲住處查訪時，發現甲攜帶行李欲遠行，經員警乙表明身分後甲仍企圖離開現場。員警乙認情況急迫，便當場將甲帶回分局偵辦，且在未通知甲之法定代理人或其他適當之人到場，即對甲進行詢問。試依少年事件處理法及相關程序法規，論述本案員警乙處理之適法性？（25 分）",
    "questionHash": "a4d959815bad441fb3df7f7b090b17d1463b38838a26c0e1f237ab7078365045",
    "sections": "少年急迫帶回與陪同詢問",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": "current-law-practice-with-version-review",
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "帶回與詢問須分別審查。擄人勒贖重罪、攜行李欲遠行可作逃匿風險資料，但依第18條之4仍須具體證明法定事由、情況急迫及不及報請法官；表明身分後想離開不等於警察可任意帶回。逕行同行後立即報請少年法院法官簽發同行書，不簽發即釋放，原則自同行起24小時內護送少年法院。詢問另依第3條之1通知法定代理人、現在保護之人或適當之人陪同；合法通知無正當理由不到或詢問本身有急迫情況才有例外。帶回急迫不能自動代替未通知即詢問的正當理由，且須告知緘默、輔佐及有利證據等權利。題未交代補簽或詢問急迫資料，應作條件式結論，不能把未記載的事實補成合法程序。",
