    "requirements": [
      {
        "text": "」請問阿宏的這種心理，最符合心理學家艾爾肯（Elkind）所提出的那一種青少年認知特徵？",
        "kind": "question-requirement"
      },
      {
        "text": "請提出兩種心理學的理論與相應的矯正方法以矯正阿宏的不當認知行為。",
        "kind": "question-requirement"
      },
      {
        "text": "辨识Elkind的個人神話及無敵感／獨特性，與想像觀眾區分；連結超速、闖紅燈與自認不會出事。",
        "kind": "question-requirement"
      },
      {
        "text": "提出兩種心理學理論，各說明作用機制及相應矯正方法；不同合理理論可接受，不限定單一範例。",
        "kind": "question-requirement"
      },
      {
        "text": "方法須回扣風險知覺與行為改變，提出可觀察的成效指標；不以責罵或單次告誡代替理論介入。",
        "kind": "question-requirement"
      }
    ],
