    "questionBody": "請從 Bandura 的社會學習理論、Bronfenbrenner 的生態系統理論及 Erikson的心理社會發展理論三種觀點，分析科技媒體如何影響青少年心理發展，並提出處遇策略。（25 分）",
    "questionHash": "85ff49aa48e62fe7c43faa99dcef989dddd1d138950c8d4c74d5f09f81038ecd",
