    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "Bandura：媒體提供模仿榜樣、替代增強與自我效能訊息，可影響行為。Bronfenbrenner：家庭、同儕與學校為微系統，家校互動為中系統，平臺政策與文化規範也影響發展，需看時間變化。Erikson：少年在認同對角色混淆中探索角色，媒體能提供探索機會也造成比較壓力。處遇包括正向榜樣及媒體識讀、家校平臺協作、支援線上線下認同探索，不把所有媒體作用視為負面。",
