    "version": "probation-190-v1-20261026-c16f0c41b3c2",
    "createdAt": "2026-10-26",
    "checkedAt": "2026-10-26",
    "questionBody": "少年事件處理法中的「少年」正處於自我認同與心靈發展的關鍵轉折期。請以榮格（Carl Jung）的分析心理學為基礎，回答下列問題：首先，請結合青少年階段的心理發展特徵，具體闡述「集體潛意識」（collectiveunconscious）、「原型」（archetype）與「個體化」（individuation）這三個核心概念的意涵。接著，請說明榮格學派會如何詮釋青少年的曝險行為，並據此論述該學派對曝險少年的治療目標為何（請至少列舉並詳細說明\n三個具體的治療目標）。（25 分）",
    "questionHash": "e7ea60e1cabd2414ac1c1940dfec63c7b7420cc26ecda8cb92bb20867800026f",
    "sections": "Jung集體潛意識、個體化及少年處遇",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": null,
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "集體潛意識是超越個人經驗、以原型形式呈現的心理結構假說；原型是組織經驗的潛在模式，英雄、陰影等意象不是人人相同的具體記憶。個體化是整合意識與潛意識、成為較完整自我的歷程，少年認同探索可視為其前期工作。曝險可能象徵追求英雄認同、排斥陰影或人格面具失衡，但須同時評估同儕、創傷與環境。目標一建立安全與情緒調節；二藉夢、繪畫與象徵探索承認被否認的感受；三整合角色與價值、發展自主負責的選擇。避免把象徵詮釋當確定病因。",
