    "questionBody": "請問少年甲先後施用第二級毒品依托咪酯及第三級毒品愷他命，兩行為均被警方同時查獲後，警察應如何移送處理？（25 分）",
    "questionHash": "a8f4748a720da492ac7201eb6fe67e69e888d14e4524adddc36005f2ab519168",
    "sections": "第二級與第三級施用的分流",
