    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "依題設第二級依托咪酯施用已觸刑罰，與第三級愷他命施用尚未觸刑罰者分開。前者依少事法第3條第1項第1款及第18條第1項移送少年法院；後者須另查健全成長保障必要，符合曝險時得通知少輔會先輔導，必要且具理由、紀錄與證據時再請求法院。兩行為同時查獲，不因此成為同一罪，也不當然使所有曝險程序一律跳過行政。卷證、尿驗及輔導資訊依法協作，避免重複或互相矛盾處遇。毒品列管時點、持有純質數量及其他犯罪若不同，須另作判斷。",
