    "questionBody": "甲於網路上販售一款宣稱有減肥功效的軟糖，有些消費者反映食用後身體不適，甲仍繼續販賣。在朋友乙推薦下，丙購買一盒放置在客廳茶几上。某日，丙外出，委託乙照顧丙 6 歲兒子 A。在乙未注意下，A 大量食用該軟糖。A 食用後逐漸出現呼吸困難與抽搐等急性中毒症狀。乙見此狀，因害怕被追究責任迅速離去。數小時後，丙回家發現 A 倒臥在地，緊急送醫後，A 仍不治死亡。法醫鑑定表示，依據現有醫學證據，若能即時給予適當醫療處置，A 死亡結果發生的風險將顯著降低。試依據中華民國刑法之規定分析甲、乙前述行為可能涉及的刑事責任。（25 分）",
    "questionHash": "d50321e37cfd4233f492486462085ff5c004b14421abf4ac95966a0f0adbb7d9",
    "sections": "食品風險、照顧保證人與不作為因果",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": "current-law-practice-with-version-review",
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "甲販售軟糖與乙受託照顧後不救，應分人、分作為及不作為檢查。對甲，先查軟糖成分、標示、食用方式、已知投訴及甲對危險的認識；有消費者不適不等於已證明殺人故意。若違反可預見的產品安全注意義務且死亡是該不容許風險的實現，可論過失致死；若證明容任傷害或死亡，才分別討論故意傷害、殺人及其結果。對乙，接受照顧六歲幼兒的約定可形成保證人義務；已見呼吸困難、抽搐仍因怕責任離去，須查求救可能、主觀故意與不作為等價性，討論不作為殺人、過失致死及有義務者遺棄致死的競合。鑑定只說即時醫療可顯著降低死亡風險，不等於已證明救助幾近確定可避免死亡；應呈現準因果關係的嚴格證明與風險降低論證，不直接把降低風險當既遂因果。若依法不能證明結果歸責，故意不作為未遂或基本遺棄等仍須另檢查，不能由死亡倒推甲乙均有罪。本題限定刑法分析；食安特別法僅於答題範圍容許時補充，不替代刑法涵攝。",
