    "title": "數位性別暴力定義與五種類型",
    "subject": "諮商與輔導",
    "version": "probation-190-v1-20261026-3d270ac5ed9b",
    "createdAt": "2026-10-26",
    "checkedAt": "2026-10-26",
    "questionBody": "請試述「網路／數位性別暴力」之定義，並請寫出五項青少年常見「網路／數位性別暴力」行為類型及做法。（25 分）",
    "questionHash": "61948c8baa02c4d9385d38d22fb9dd9654dd53c50d249f8539bd46ad8a89bcd1",
    "sections": "數位性別暴力定義與五種類型",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": null,
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "數位性別暴力是利用網路或數位工具，基於性別或性而侵害他人尊嚴、安全、自主的行為，可與實體暴力相連。五類例子：未經同意散佈私密影像；以影像威脅勒索或逼迫性交；傳送不受歡迎的性訊息與影像；性別仇恨、羞辱及網路群體攻擊；科技跟蹤、公開個資或冒用身分騷擾。重點是未經同意、權力與侵害，不把自願性表達一概列為暴力。處遇保留證據、限制接觸、平臺申訴及依法通報，避免責怪受害者或要求其反覆展示影像。",
