    "questionBody": "幸福感被認為是人們心理健康狀態的重要指標之一，塞利格曼（MartinSeligman）提出「積極富能（Flourishing）」為幸福感指標，且以五個向度來定義「積極富能」，試闡述這五個向度及其在促進青少年心理健康可能的應用。（25 分）",
    "questionHash": "1a211fc8e22cd156f8f94d17aab62e7f7ac596e91aaf9c7563d9187f7ccef0c1",
    "sections": "PERMA五向度與少年心理健康",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": null,
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "PERMA包括正向情緒、投入、關係、意義及成就。對少年，可用感恩與情緒辨識增加正向經驗，以適度挑戰的活動促進投入，建立支援性同儕與成人關係，透過服務探索價值與意義，設定可達成小目標累積成就。五向度可各自促進福祉，不等於時時快樂；遇憂鬱、自傷或創傷仍需適當評估與專業處遇。",
