    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "Bandura將攻擊視為學習與情境互動作用；激起因素可涵蓋厭惡經驗／挑釁、誘因、榜樣攻擊、命令指示與妄想等不正常信念的影響。例如受辱引起怒氣，預期獲地位而攻擊，旁觀暴力被獎賞或接受上級命令；並非每次挫折必然攻擊。需區分獲得行為、當下激起和維持增強，個人的認知、道德自我制裁與自我效能調節表現。若教材分類不同須核對1977著作，用實際機制與例子評估，不能僅用五關鍵字判正確。",
