    "questionBody": "請說明犯罪行為發生之個人、家庭、社區與社會風險因素，並列舉二個研究案例加以說明。（25 分）",
    "questionHash": "c9aadf8844791c0495376c7af9012e5675fbca45530a350ea861cf7fdcdb86c4",
    "sections": "四層風險與兩個研究案例",
    "draft": false,
