    "referenceAnswer": "個人風險如衝動、早期行為問題、物質使用；家庭如虐待、監督失衡與關係衝突；社群如資源不足、暴力暴露與低集體效能；社會如排除、不平等與不當制度。兩研究可舉Pittsburgh少年縱貫研究，辨識公開、隱蔽與權威衝突路徑及累積風險；Sampson等芝加哥社群研究，發現互信與非正式控制的集體效能與暴力較低相關。說明樣本、方法、發現及限制，不能以橫斷相關當因果，避免把貧困或家庭結構直接當必然犯罪。",
