    "questionBody": "甲長期酗酒而犯故意毀損罪，經被害人合法告訴，檢察官起訴甲後，法院於審判程序中，認為甲所涉犯之毀損罪，其犯罪事實尚待釐清，但因甲酗酒成癮，且有強烈再犯毀損罪之虞，有立即宣告禁戒處分之緊急必要性，法院得否於本案判決前，先行以裁定宣告禁戒處分？（25 分）",
    "questionHash": "10d3ff5250ffe9974ab103025f3256bb023fe55b7c1bac0c44d5befee53f45cb",
    "sections": "判決前緊急禁戒",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": "current-law-practice-with-version-review",
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "保安處分執行法第4條第2項明文例外，法院對應付監護、禁戒或強制治療之人認有緊急必要時，得於本案判決前先以裁定宣告；同條也規範偵查中檢察官聲請。甲須符合刑法第89條因酗酒犯罪、成癮及再犯危險等基礎，法院應查清症狀、危險、立即處遇與比例，不能只因酗酒標籤即拘禁。犯罪事實尚待釐清不使法定例外一律失效，但更不能免除實體與證據要求；須保障陳述及救濟。依第4條，收受送達後五日內可抗告，抗告原則不停止執行，原審或抗告法院得裁定停止。應區別禁戒的緊急裁定與一般併於裁判宣告原則。",
