        "採說後回扣具體危險。",
        "乙自行高速駕駛失控死亡，不使甲當然成立第185條第2項致死，須另審共同創設風險、死亡歸責與結果加重之預見可能；",
        "對自主參與競速者的自我負責風險應提出論證。",
