    "referenceAnswer": "王於112年7月已15歲，適用少年範圍。依題設施用第三級毒品且未另觸刑罰，仍須依第3條判斷成長保障必要，不能僅陽性尿驗就省略需求評估。咖啡包1.3822公克為驗餘淨重，不等於法定純質毒品重量，亦不可僅見重量便認刑事持有罪。警方知有曝險得通知少輔會，由行政輔導先行；必要且附理由、輔導紀錄資料及證據，再請少年法院處理。尿液為檢驗證據，毒品咖啡包為行為所用、所生或所得之物，兩者取得、保管及處理法源應分別核對；第18條第7項有扣留保管及沒入、銷毀、發還等制度，不能把所有檢體都當違禁物立即銷毀。",
