    "requirements": [
      {
        "text": "王 OO 係民國 97 年 5 月 11 日出生，明知愷他命（以下簡稱 K 他命）、硝甲西泮均係毒品危害防制條例第 2 條第 2 項第 3 款所列管之第三級毒品，依法不得施用，竟基於施用 K 他命、硝甲西泮之犯意，於 112 年 7月 1 日 14 時許，在新北市中和區 O 路 O 段 O 號之友人住處，以將 K 他命粉末摻入香菸內再點火吸食，又將毒品咖啡包混入蠻牛飲料後飲用等方式，施用 K 他命、硝甲西泮各乙次，嗣於 112 年 7 月 2 日 11 時 48 分許，在新北市中和區 O 路 O 段 O 號前，員警見王 OO 形跡可疑乃上前盤查，當場查獲含硝甲西泮成分之毒品咖啡包 1 包（驗餘淨重 1.3822 公克），經警於同日 12 時 53 分許採集其尿液送驗結果，檢出 K 他命呈陽性反應，始供承上情。試問：",
        "kind": "question-requirement"
      },
      {
        "text": "（一）王 OO 先後所為，是否屬於現行少年事件處理法第 3 條第 1 項所定應處理之情形？",
        "kind": "question-requirement"
      },
      {
        "text": "（二）司法警察官於執行職務時，知王 OO 有上述情形，應如何處理？",
        "kind": "question-requirement"
      },
      {
        "text": "（三）司法警察機關如何處理採集之尿液及查獲之毒品咖啡包？",
        "kind": "question-requirement"
      }
    ],
