    "requirements": [
      {
        "text": "甲為 A 保健食品公司代表人，明知由乙所拍攝之小草益生菌膠囊照片及所製成之廣告圖片，均屬乙享有著作財產權之著作，未經乙之同意或授權，不得重製及公開傳輸。詎甲在公司上網時看到乙之前開著作，遂加以重製並上傳至 A 公司網站，藉以行銷 A 公司之益生菌產品。甲之住居所在新竹市，A 公司設在桃園市，乙之住居所在臺中市，乙外出在臺南市上網瀏覽時發現 A 公司盜用其照片，擬對 A 公司及其負責人甲提出侵害著作權之告訴。請論述：",
        "kind": "question-requirement"
      },
      {
        "text": "（一）何地之法院對本案有管轄權？",
        "kind": "question-requirement"
      },
      {
        "text": "（二）如乙就地向臺南地方檢察署提出告訴，檢察官應如何處理？如檢察官向臺南地方法院起訴，法院應如何處理？",
        "kind": "question-requirement"
      },
      {
        "text": "（三）如乙回到家後才向臺中地方檢察署提出告訴，檢察官應如何處理？如檢察官向臺中地方法院起訴，法院應如何處理？",
        "kind": "question-requirement"
      }
    ],
