        "乙不在場不當然免教唆、幫助或具有功能支配的共同正犯，但也不能只因傳話就認與全部後續暴力有共犯。",
        "丙擊A、B與甲眾後續衝突應按傷害故意、傷勢及共犯範圍審277等罪；",
        "臨時升級暴力是否過剩須按可知、容任及計畫範圍論證。",
        "到場依法執勤C警死亡，除135一般妨公，尤其應審136聚眾妨害公務及其致死規定；",
