    "questionBody": "觸犯槍砲彈藥刀械管制條例及涉及故意傷害罪被判刑 3 年的甲男，在諮商中向你透露他想越獄去探望因車禍受重傷的母親，並請你不要告訴他人。請說明你將如何處理這種情況與進行個案諮商的方法。（25 分）",
    "questionHash": "19bb693604d9e162952cb9239a73812c04879cbca728091fabd25791c73cc6a3",
    "sections": "越獄透露的保密及危機諮商",
    "draft": false,
