    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "先同理母親重傷的焦慮，說明保密及安全例外；不承諾替越獄計畫保密。評估意圖、時間、工具、協力者、傷人及自傷風險，依職務法律與機關規範向必要安全及醫療單位揭露最低必要資訊並紀錄、督導。協助申請合法探視、通訊、視訊或依法可用的外出途徑，不保證核准。諮商採危機穩定、認知與問題解決、支援系統動員，與個案共同擬安全計畫，持續追蹤。保密例外需個案評估，不能把所有情緒性語句一概當立即越獄。",
