    "version": "probation-190-v1-20261026-cf1784455c05",
    "createdAt": "2026-10-26",
    "checkedAt": "2026-10-26",
    "questionBody": "性平三法內涵為何？高三青少年乙女向你投訴國小五年級時導師見其駝背，假好心幫她矯正姿勢，冷不防把手伸進衣服，摸她胸部與私處，感覺痛苦至今，請問此事件應適用何法規處置？身為觀護人或輔導員有那些輔導處遇方式？（25 分）",
    "questionHash": "214fbf1b91ee2ab23cbc39619762d1f9b186940d2649ae783bc26baed79f5c5d",
    "sections": "性平三法分工與早年校園性事件",
