    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "性平三法為性別平等教育法、性別平等工作法及性騷擾防治法；依身分與事件場域區分，不能自由選擇規避專法。當時師生間的校園性侵害或性騷擾，應循性平教育法校園事件機制，摸胸部私處另須依具體事實評估刑事責任與兒少保護；不因多年後揭露就直接認定全部救濟失效。輔導先保護安全、傾聽且不逼問，依法通報並轉介學校／主管機關與司法、醫療及創傷服務，支援當事人選擇、告知程序及保密限制。不讓輔導取代調查，也不安排強迫和解。",
