    "questionBody": "Corey 將團體諮商歷程分為那幾個階段？請分別說明各個階段的主要內涵，並以青少年霸凌防治團體治療計畫（六次團體）為例，列出名稱、輔導重點及各個階段可使用的諮商技巧。（25 分）",
