    "referenceAnswer": "可依Corey分準備、開始、轉換、工作、結束與後續評估；教材有將準備及後續獨立的分類，需先明示。六次防霸凌團體示例：1相識與契約，建立安全保密；2辨識霸凌與情緒，反映及教育；3面對不信任，處理抗拒與角色演練；4同理及旁觀者介入，回饋與行為排練；5衝突解決，問題解決和新行為練習；6整合道別與行動計畫，摘要及追蹤。開始重信任，轉換處理焦慮權力，工作深化互助，結束處理分離。階段不是每次課固定一階段。",
