    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "先分少年保護事件與少年刑事審判。少事法第42條第2項治療處分是保護處分之前或同時針對少年身心障礙的處遇，文字不等於刑事案件可不經其他要件直接安置。少年刑事案件如依第1條之1準用刑訴第121條之1，須有犯罪嫌疑重大、刑法第19條責任能力原因可能存在、公共安全危險及緊急必要，經法官訊問後作暫行安置；偵查依檢察官聲請，審判得依聲請或職權。基本期間六月以下、每次延長不逾六月、累計不逾五年，並有抗告。比較時從目的與程序、適用對象、實體要件、處所、期間及救濟說明。刑事案是否另可準用第42條治療，仍應以程序性質相容與法律保留論證，不能由保護目的跳過嚴格拘束要件。",
