        "text": "少年刑事被告於案件審理中如精神狀態顯有缺陷而有危害公共安全之虞時，請分別說明以下：法院能否依少年事件處理法第 42 條第 2 項第 2 款規定令入相當處所實施治療或依刑事訴訟法第 121 條之 1 規定令入司法精神醫院等處所施以暫行安置？",
