    "checkedAt": "2026-10-26",
    "questionBody": "請說明修復式司法於少年事件之應用上，若少年堅持不道歉或對話會否造成不利益。（25 分）",
    "questionHash": "341e3ddd75009d1f57c1bba01702c4d6ef33e83c4a0d621602bdc2d4db753431",
    "sections": "拒絕道歉或修復對話的效果",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": "current-law-practice-with-version-review",
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "依第29條第3項及第42條第4項，少年修復、道歉、悔過或賠償等程序具有同意要求。少年拒絕道歉或對話，不應單憑拒絕便認無悔意或加重保護處分；否則形式自願將變成強迫。應先說明目的、保密、安全、選擇及退出界線，尊重少年與被害人自主，檢查權力不平等、心理風險及是否準備好參與。法院仍依行為證據、需保護性及法定處遇決定，而非參加就必定不付審理，或拒絕即認犯罪。可探索其他合法負責方式，但不能以修復取代防禦權、否認權或被害人不參與的權利。",
