    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "先查少年拒絕的正當原因、身心需求、環境安全及服務適切性，採支持、協調及紀錄，不能由機構自行拘禁或轉感化。第55條之3針對無正當理由拒絕安置等處分，法定聲請人可請少年法院核發勸導書，經勸導無效再聲請法院裁定五日內留置觀察。安置中違反事項情節重大，或經觀察後再違反而難收效果，依第55條之2檢具事證聲請撤銷安置，法院可將餘期改感化；餘期不滿六月者執行至六月。另依安置成效、機構適合度或需求，法定免除、延長或變更有不同要件，不可將抗拒一概當升級制裁。",
