    "createdAt": "2026-10-26",
    "checkedAt": "2026-10-26",
    "questionBody": "父母親對於子女的監控不足或過度都可能造成負面的影響，請各別以一犯罪學理論說明監控不足與過度可能造成的負面影響。（25 分）",
    "questionHash": "974dab9f82bd3dd7c5da041ddf3730cd86d895533ec3cd1ecbbdeb24566cd4d6",
    "sections": "監控不足與過度各一理論",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": null,
    "contentStatus": "targeted-source-review",
