    "referenceAnswer": "少年重自主、同儕認同而抽象反省能力仍在發展。以開放問句、同理反映、情緒命名、行為事件鏈、角色演練、繪畫或量尺促進覺察，使用短而具體語言及共同目標，避免說教與貼標籤。例如偷竊少年重建事前念頭與同儕壓力，再排練拒絕。跨專業依需求合作學校、家庭、社工、心理與精神醫療、就服、少年司法及觀護，設共同計畫和最少必要資訊分享；沒有單一團體對所有少年最有效，須依風險與成效調整。",
