    "questionBody": "訓誡及假日生活輔導之執行主體及方法為何？少年無正當理由拒到院執行，應如何處置？（25 分）",
    "questionHash": "45c18e753f371b29399acded7cbd20d2c70952b992b5830c6cf3b8a0e89ef07d",
    "sections": "訓誡假日輔導與拒絕執行",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
