    "legalVersion": "current-law-practice-with-version-review",
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "第50條訓誡由少年法院法官指明不良行為、告知將來遵守事項，可命悔過書，並通知法定代理人或現在保護少年之人及輔佐人在場。假日生活輔導為三至十次，由法院交少年保護官於假日施個別或群體教育、學業及其他作業輔導並得命勞動服務，次數按成效決定，也可依法交適當機關團體個人並受指導。少年無正當理由拒絕，先確認合法通知與障礙，再依第55條之3由法定聲請人請法院勸導，無效時聲請法院五日內留置觀察；第59條通知、同行及協尋的權限另分法官與保護官。不得保護官或機構自行拘禁，正當病況交通等障礙不等於無理由抗拒。",
