    "title": "情緒四成分的動態運作",
    "subject": "心理學",
    "version": "probation-190-v1-20261026-2991081b8276",
    "createdAt": "2026-10-26",
    "checkedAt": "2026-10-26",
    "questionBody": "在 COVID-19 的疫情變化下，人們的情緒跟著起伏不定，而此起伏可能影響身心健康。情緒也如同濾鏡般，讓人對事物有不同的感受和判斷。情緒的動態與多層次，提供我們分析人的行為。試以情緒的四個元素說明情緒的運作特性。（25 分）",
    "questionHash": "eff9005b4ce627aa5ff7cbd8b9f21aefe5f370bac1a8f449a81bc8c262b413aa",
    "sections": "情緒四成分的動態運作",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": null,
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "情緒可從主觀感受、生理喚起、認知評估及行為／表達四成分理解。疫情中，感染風險的評估引發害怕，伴隨心跳加速，主觀焦慮及迴避或求助行為；成分彼此回饋，會隨資訊與情境變動。不同教材對成分命名略有差異，有清楚定義與例項者可接受；情緒不等於單純生理反應，也不必然導致同一行為。",
