    "createdAt": "2026-10-26",
    "checkedAt": "2026-10-26",
    "questionBody": "請說明「支持問責圈」（Circles of Support and Accountability, CoSA）的運作模式，及其如何使高風險的性犯罪者重新適應社會的原理。（25 分）",
    "questionHash": "f3bd0c175dbfa2bc209aa2292a7fcc8e95f04bed3565065e9793346d2b3be258",
    "sections": "CoSA運作與復歸原理",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": null,
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "CoSA以核心成員即性犯罪出監者與受訓練志工形成內圈，專業人員與司法醫療組成支援外圈。定期會面、建立生活資源、減少孤立，並誠實面對風險、檢視安全計劃、必要時向專業體系通報；原則是無人可被丟棄、同時不再製造被害者。支援與問責並行促進親社會認同、日常結構和及時發現動態風險。非取代法定監督、非無條件保密或保證零再犯，志工需篩選訓練、督導、界線與成效評估。",
