    "referenceAnswer": "心理動力覺察重在理解無意識衝突、防衛、早期關係及重複模式，透過自由聯想、夢、移情與詮釋把無意識帶入意識。存在取向重在覺察當下處境、死亡、自由責任、孤獨及意義，探索逃避選擇與較真誠生活。兩者都增進自我理解和關係，但前者較強調歷史與內在動力、詮釋重複關係，後者較強調此刻及未來可能、選擇與責任。這是重點差異，不代表動力治療不談當下或存在治療不談過去。",
