    "questionBody": "多元文化能力（Multicultural Competence）是諮商輔導的核心基本能力之\n一，請簡介及說明多元文化能力的四個基本要素，再以「遭受家庭暴力的受害女性」為對象，論述前述多元文化能力的實務應用。（35 分）",
    "questionHash": "3fd75a8fcaf2e0323b4d4a29df46bf39afd6c8456846221e26fa5f9d94668727",
