    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "先明示採用的能力架構。若採2015年MSJCC的AKSA四項能力，可分態度與信念、知識、技巧、行動：態度與信念是覺察自己的性別、文化與婚姻價值及權力偏見；知識是了解案主語言、族群、階級、移民身分、家庭權力與制度障礙；技巧是以文化適切且可理解的晤談、危險評估與安全計畫回應需求；行動是把能力落實為轉介、資源取得和減少制度排除。對家暴女性，不責問為何不離開，評估離開或暫留的安全與資源限制，尊重選擇而不以文化合理化暴力。若改採MSJCC四個發展領域，應完整列為諮商員自我覺察、案主世界觀、諮商關係、諮商及倡議介入，逐項應用，不能把領域名稱與AKSA成分混成一組。原題未指定模型，其他有明確來源且完整應用的架構可接受。",
