    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "原題引舊條次，現行法校園性騷擾／性霸凌行為人處置應核對現行條文，不直接沿用25條。輔導人員需說明被命接受輔導的法源、非自願性、保密例外與報告用途；取得必要法定代理人同意並尊重少年知情參與，兼顧被害人安全。避免同時擔任調查、裁決及治療造成角色衝突；只提供必要出席、風險或處遇資訊，不任意交出全部談話。評估性別權力、情緒及行為責任，禁止強迫和解或以輔導免責，具備能力、接受督導、必要時轉介。",
