    "checkedAt": "2026-10-26",
    "questionBody": "流體智力（fluid intelligence）與晶體智力（crystallized intelligence）的差異為何？兩者在個體人生全程發展之消長及意涵為何？並請論述對個體職涯發展之可能影響。（25分）",
    "questionHash": "2bb0768c10e723355304aefb50d74de4c2a1d276f658b595d3a09b3ac26bc000",
    "sections": "流體與晶體智力的全程變化",
