    "referenceAnswer": "流體智力是處理新問題的推理與適應能力，較不依賴已學知識；晶體智力是文化、教育及經驗累積的知識技能。流體能力通常較早達峰並隨年齡下降，晶體能力往往維持或增長較久，但有個別差異。職涯可用持續學習支援新技能，並發揮成熟工作者的知識與專業判斷；不能以年齡否定能力或把兩者視為互不相關。",
