        "潛在特質重較穩定個體傾向如低自我控制、衝動，犯罪次數隨年齡和機會變化而相對傾向可保持。",
        "比較穩定來源、變化機制、個體與情境權重、政策：前者強化轉銜關係機會，後者早期親職與能力發展。",
