    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "甲對無罪判決附帶的監護處分有實質不利益及救濟利益，不能只看無罪主文便認無上訴利益。現行刑訴第348條明文可明示僅就保安處分一部上訴；第301條第2項亦規範不罰而有必要時併諭處分及期間。爭執應針對刑法第87條再犯或公共危險、治療必要與比例及期間，精神鑑定只是證據，不取代法院判斷；僅自稱正常也不當然證明無必要。若實際處分另以裁定作成，救濟形式須依裁判性質辨抗告；本題既為無罪判決併諭監護，原則循判決上訴。",
