    "referenceAnswer": "先確認乙臨檢、酒測及錄影蒐證為依法執行職務，甲以拳攻擊可該當135妨害公務；拒酒測與酒駕刑責、毆警刑責分開，不因未測得酒精即排除妨公。左眼治療後僅0.1且只能見50公分內，應依刑法第10條第4項『一目或二目視能毀敗或嚴重減損』及持續功能判斷，不能把任何視力下降都當重傷，也不能因另一眼仍正常便排除。甲有一般傷害故意而重傷可預見，可論277第2項傷害致重傷；若證明甲已容任嚴重減損視能，則審278故意重傷。135第4項致公務員重傷的結果加重，仍須暴力與重傷因果及17條預見，不能把揮拳一律等同重傷故意。妨公與身體法益可按同一行為的競合處理，並交代為何採故意重傷或加重結果，不重複計算同一結果。",
