        "同心圓政策說明是立法目的及體系解釋，不宜將家庭學校社區排成法定一律必經的固定層數。",
        "尚未經獨立專業人工審閱或命題答案集校準；有理由的不同見解仍須覆核。",
        "尚未經獨立專業人工審閱或專家答案集校準；同義表達、合理異說及實質正確性須覆核。",
