        "text": "108 年 6 月 19 日由總統公告施行之新修正少年事件處理法乃依同心圓理論，而對曝險少年採「行政輔導先行，以司法為後盾」之作法，請依新修正規定，對其立法理由及具體規範詳予說明。",
