    "questionBody": "請依 108 年 6 月 19 日由總統公告施行之新修正少年事件處理法第 83 條之 1，關於塗銷少年前案紀錄及有關資料之規定，就下列問題，詳予說明：（一）少年法院於何情形下，應通知保存少年前案紀錄及有關資料之機關、機構及團體，將少年之前案紀錄及有關資料予以塗銷？（12 分）（二）本條所謂「前案紀錄及有關資料」，其範圍為何？其與少年及兒童保護事件執行辦法第 31 條所規定應通知各保存少年前科紀錄及有關資料之機關（構）塗銷之範圍有無不同？（8 分）（三）本條所謂「塗銷」，目前之實務作法為何？（5 分）",
    "questionHash": "c3184db8f5689f2e03d7181db398d4daef51deb366282a604d6eac411b937942",
    "sections": "塗銷時點、範圍與實務作法",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": "current-law-practice-with-version-review",
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "第一問先依第83條之1列塗銷時點：第29條轉介處分執行完畢二年；保護處分或刑執行完畢、赦免三年；不付審理或不付保護處分裁定確定；另有緩刑滿未撤銷、無罪免訴不受理確定、緩起訴滿未撤銷及依法通知之不起訴。第二問比較原題舊『少年及兒童保護事件執行辦法』第31條，其列轉介二年、保護或刑三年、不付審理、不付保護及無罪等六款，與108修法新增緩刑、緩起訴、不起訴、免訴及不受理等保護範圍不同；該舊辦法已廢止，只作歷史比較。現行施行細則第18條將業務建立的移送、調查、偵查、審理及執行紀錄列為前案資料，但不含為辦案編纂的卷宗，應與卷宗本身的保存及閱卷限制區分。第三問依現行管理辦法第3條及施行細則第17條，塗銷可採塗抹、刪除、遮掩、加密、去連結、封存、銷毀等使人無法識別少年身分的方法，不等於一律物理銷毀全部原卷；管理辦法另規範通知及回報。",
