    "questionBody": "何謂人際吸引（interpersonal attraction）？人際吸引的影響要素為何？（25 分）",
    "questionHash": "a5932ae68aad107627b458632c9dfbfa2c792925b762712ddbbf774ea50da3c5",
    "sections": "人際吸引的定義與因素",
