    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "人際吸引是對他人接近、交往及維持關係的正向傾向。常見因素有接近與接觸機會、熟悉性、相似態度價值、互惠喜好、外貌及情境喚起；需求、依附與文化也影響。可用同學因常合作及共有興趣而親近說明，並指出接觸不一定產生喜好，衝突、偏見與個別差異可能改變效果。",
