    "title": "公共衛生三層犯罪預防",
    "subject": "犯罪學",
    "version": "probation-190-v1-20261026-aa8402c3f4ef",
    "createdAt": "2026-10-26",
    "checkedAt": "2026-10-26",
    "questionBody": "每一項犯罪問題的發生，都會讓社會、國家付出鉅大的成本，所以如何讓犯罪不再發生或減少發生是一項重要的課題。學者 Brantingham 及Faust 藉公 共 衛 生 疾 病預 防 模 式（ Public Health Model of DiseasePrevention）提出目標導向之公共衛生犯罪預防模式，其理論內涵是如何架構應用在犯罪預防工作上？請詳述之。（25 分）",
    "questionHash": "f9edc79b414c59391f9b2c0ceb05eda0f8dbf14aacbd17a5771711ffec3b94dd",
    "sections": "公共衛生三層犯罪預防",
    "draft": false,
