    "referenceAnswer": "公共衛生目標模式分初級、次級、三級：初級對一般人和環境，在犯罪發生前降低機會與結構風險，如學校支援、安全設計；次級對高風險者或地段早期辨識與介入，如家庭支援、熱點問題解決；三級對已有犯罪者減少再犯與損害，如治療、觀護和復歸。須交代各物件、時間、目標和例子，資源依證據分配並評估成效。類別可能重疊且非三級一定最嚴厲，避免把高風險識別變為汙名或只以逮捕數判效果。",
