    "version": "probation-190-v1-20261026-19464ebab838",
    "createdAt": "2026-10-26",
    "checkedAt": "2026-10-26",
    "questionBody": "甲為性侵害案件之假釋出獄人，假釋期間付保護管束，經執行檢察官依性侵害犯罪防治法第 20 條第 3 項規定，施以宵禁並輔以電子腳鐐，屢次違規，於保護管束期間再犯竊盜及毒品案經起訴後，某日以電話通知觀護人電子腳鐐脫落後即逃匿無蹤，檢察官以最速件報請撤銷假釋，惟撤銷假釋行政程序冗長，緩不濟急，檢察官恐其四處流竄，再犯性侵案件造成社會不安，促請警方協助追蹤。試問，保安處分執行法第 66 條所稱之「必要時，得限制受保護管束之人之自由」，應如何解釋及適用為適當？（25 分）",
    "questionHash": "243bd3d6b694f5b8634164587dd96f4f7b64c5f845981c6ea6a594933bd96ce8",
    "sections": "保安執行法66自由限制界線",
    "draft": false,
    "reviewStatus": "trial-unvalidated",
    "scoringMode": "conservative-text-evidence",
    "legalVersion": "current-law-practice-with-version-review",
    "contentStatus": "targeted-source-review",
    "sourceNote": "逐題教練要點，非官方配分或唯一答案；文字線索不等於正確性，待查證內容不自動判對或判錯。",
    "changeNote": "保留完整原題，新增本題四項試評理由、要求檢查及來源狀態。",
    "referenceAnswer": "第66條給指定遵守事項、告誡及報請檢察官適當處理的執行框架，末句必要自由限制須與其目的、人身自由法律保留及比例併讀，不能僅因恐再犯便無期限拘禁。先記錄宵禁、裝置脫落與失聯，查故意逃避或故障，向檢察官報告並依法協尋；需拘提逮捕羈押時，另循明確刑事要件與司法審查，協尋不得替代。撤假釋程序久不創設新拘禁權；新案起訴不等於判決有罪。可說明對短暫執行到場限制的較寬解釋與嚴格法律保留見解，但須交代強度時間、必要及救濟，並區別法定性犯罪監控處遇。",
